/** @jsxImportSource kerfjs */
import { delegate } from 'kerfjs';
import { Toolbar } from '@kerfjs/ui/toolbar';
import { ToolbarText } from '@kerfjs/ui/toolbar-text';
import { ToolbarControlGroup } from '@kerfjs/ui/toolbar-control-group';
import { SegmentedControl } from '@kerfjs/ui/segmented-control';
import '@kerfjs/ui/layout.css';

export type WorkspaceView = 'board' | 'list' | 'timeline';
export type WorkspaceAction = { type: 'workspace.view.change'; value: WorkspaceView };

// A compact presentation choice within one workspace; no tabpanels or tab roles.
export function createWorkspaceView(
  id: string,
  initialValue: WorkspaceView,
  dispatch: (action: WorkspaceAction) => void,
) {
  let value = initialValue;
  const render = () => <div class="kui-layout">
    <Toolbar label="Workspace controls"
      leading={<ToolbarText text="Workspace" size="small" />}
      trailing={<ToolbarControlGroup label="View controls">
        <SegmentedControl id={id} label="Workspace view" value={value}
          action="workspace.view.change" appearance="toolbar" size="small"
          choices={[
            { value: 'board', label: 'Board' },
            { value: 'list', label: 'List' },
            { value: 'timeline', label: 'Timeline' },
          ]} />
      </ToolbarControlGroup>} />
  </div>;
  function connect(root: HTMLElement, invalidate: () => void) {
    const dispose = delegate(root, 'click', '[data-action="workspace.view.change"]', (_event, element) => {
      const next = element.getAttribute('data-segment-value');
      if (next !== 'board' && next !== 'list' && next !== 'timeline') return;
      if (value === next) return;
      value = next;
      dispatch({ type: 'workspace.view.change', value: next });
      invalidate();
    });
    // Native buttons keep every enabled option in Tab order; Enter/Space
    // activate the same delegated action. No competing roving-tabindex helper.
    return dispose;
  }
  return { render, connect, setValue(next: WorkspaceView) { value = next; } };
}
